def write():
    assert len(CASES)==20
    audit=json.loads((OUT/'denetim-sonucu.json').read_text(encoding='utf-8'))
    for i,pairs in enumerate(CASES,1):
        path=OUT/f'ev-sohbet-02-{i:02}.json';record=json.loads(path.read_text(encoding='utf-8'))
        result=next(r for r in audit['results'] if r['id']==record['id'])
        living=next(s for s in record['plan']['spaces'] if s['kind']=='living' and s['level_id']=='level-0')
        def fmt(v):return f'{v:.1f}'.replace('.',',')
        fields=dict(net=fmt(record['claimed_net_area_m2']),living=fmt(area(living)),items=len(record['plan']['items']),exceptions=len(result['source_exceptions']))
        record['dialogue']=[dict(role=role,content=text.format(**fields),language=record['language'],turn=turn) for turn,pair in enumerate(pairs,1) for role,text in zip(('user','assistant'),pair)]
        record['source_exceptions']=result['source_exceptions']
        record['scenario_status']='fictional_conversation_on_licensed_reference_not_customer_or_model_transcript'
        for op in record['operations']:
            op['conversation_turn']=2 if op['kind'] in ('rigid_transform','node_compatibility_wall_axes') else 3
        if record['plan'].get('stairs'):next(op for op in record['operations'] if op['kind']=='propose_second_floor_and_stair')['conversation_turn']=2
        record['operations']=[op for op in record['operations'] if op['kind']!='furniture_solver_request']
        for request in record['layout_requests']:
            last=request['attempts'][-1]
            record['operations'].append(dict(kind='furniture_solver_request',space_id=request['space_id'],
                conversation_turn=6 if i==15 and record['plan']['spaces'][next(j for j,s in enumerate(record['plan']['spaces']) if s['id']==request['space_id'])]['kind'] in ('kitchen','bath') else 5,
                selected_items=[x['id'] for x in last['items']] if last['result']['ok'] else [],
                alternative_accepted_turn=6 if request['requires_user_acceptance_of_reduced_set'] or not last['result']['ok'] else None,
                outcome='placed' if last['result']['ok'] else 'unresolved_user_keeps_open_question',
                solver_request_index=record['layout_requests'].index(request)))
        dump(path,record)
    print('20 individually authored conversations; 160 exchanges, 320 messages')

if __name__=='__main__':write()
